}

// app/theme-provider.tsx
'use client';

import { createContext, useContext } from 'react';

const ThemeContext = createContext<{ theme: string; onChange: () => void } | null>(null);

export function ThemeProvider({ theme, onChange, children }) {
  return (
    <ThemeContext.Provider value={{ theme, onChange }}>
      {children}
    </ThemeContext.Provider>
  );
}

scenarios.modelAnswer:
The failing value is `onChange`. `RootLayout` is a Server Component and `ThemeProvider` is marked `'use client'`, so every prop it receives crosses the RSC boundary and must be serializable. A closure created during the server render — `() => db.prefs.save(theme)` — is not: React cannot ship server code as a prop value. The one function-like value that may cross is a **Server Function reference**, because the framework replaces it with an endpoint the client can call.

`children` is the other half of the lesson. It already holds rendered server output, so passing it through a Client Component does not turn those pages into client code. The provider is a client boundary *around* a server subtree, not a conversion of the subtree — which is exactly why the boundary should sit as low as practical.

**Refactor**

- The layout fetches the theme and passes a serializable value (`'light' | 'dark'`).
- Theme state lives in the client provider (`useState`), so switching is instant and local.
- Persistence is a Server Function in its own file, imported directly by the client module. Importing it is the supported crossing; handing a closure through props is not.

```ts
// app/actions.ts
'use server';

import { cookies } from 'next/headers';

export async function saveTheme(theme: 'light' | 'dark') {
  (await cookies()).set('theme', theme, { httpOnly: true, sameSite: 'lax' });
  return { ok: true };
}
```

```tsx
// app/layout.tsx
import { ThemeProvider } from './theme-provider';
import { getTheme } from '@/lib/theme';
import type { ReactNode } from 'react';

export default async function RootLayout({ children }: { children: ReactNode }) {
  const theme = await getTheme(); // 'light' | 'dark', serializable

  return (
    <html>
      <body>
        <ThemeProvider initialTheme={theme}>{children}</ThemeProvider>
      </body>
    </html>
  );
}

// app/theme-provider.tsx
'use client';

import { createContext, useContext, useState, useTransition, type ReactNode } from 'react';
import { saveTheme } from './actions';

type Theme = 'light' | 'dark';
const ThemeContext = createContext<{ theme: Theme; setTheme: (t: Theme) => void } | null>(null);

export function ThemeProvider({ initialTheme, children }: { initialTheme: Theme; children: ReactNode }) {
  const [theme, setThemeState] = useState(initialTheme);
  const [, startTransition] = useTransition();

  function setTheme(next: Theme) {
    setThemeState(next);
    startTransition(() => saveTheme(next)); // Server Function call, not a function prop
  }

  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>{children}</ThemeContext.Provider>
  );
}

export function useTheme() {
  const ctx = useContext(ThemeContext);
  if (!ctx) throw new Error('useTheme must be used inside ThemeProvider');
  return ctx;
}
```

**Why not just mark the layout `'use client'`?** Because it would pull the layout, its imports and everything it renders into the client bundle and end server rendering for the whole segment — the shortcut this boundary discipline exists to prevent. Keep the directive at the leaf that needs state.

One finishing detail: the client state makes the switch instant, but any server-rendered consumer still reads the old value until the cookie write is reflected — revalidate the affected path or tag after `saveTheme` when the server tree must agree with the browser.

Two adjacent traps worth naming: passing a `Map`, `Set` or `Date` is fine because those are serializable, while passing a class instance (an ORM client, a stream) fails like the function did — the boundary serializes values, it never shares memory.
